"use client";

import { keepFormOnSubmit } from "@/lib/use-keep-form";
import { useActionState, useTransition } from "react";
import { changePassword, deleteAddress, saveAddress } from "@/app/actions/account";

export function ChangePasswordForm() {
  const [state, action, pending] = useActionState(changePassword, undefined);
  return (
    <form action={action} onSubmit={keepFormOnSubmit(action)} className="space-y-3">
      <input name="current" type="password" placeholder="Current password" autoComplete="current-password" className="input" required />
      {state?.fieldErrors?.current && <p className="text-xs text-danger">{state.fieldErrors.current[0]}</p>}
      <input name="next" type="password" placeholder="New password" autoComplete="new-password" className="input" required minLength={8} />
      {state?.fieldErrors?.next && <p className="text-xs text-danger">{state.fieldErrors.next[0]}</p>}
      {state?.error && <p className="text-xs text-danger">{state.error}</p>}
      {state?.ok && <p className="text-xs text-success">Password updated. Other devices have been signed out.</p>}
      <button disabled={pending} className="btn-outline">Update password</button>
    </form>
  );
}

export function AddressForm() {
  const [state, action, pending] = useActionState(saveAddress, undefined);
  const err = (k: string) => state?.fieldErrors?.[k]?.[0];
  return (
    <form action={action} onSubmit={keepFormOnSubmit(action)} className="grid gap-2 sm:grid-cols-2">
      <input name="name" placeholder="Full name" className="input" required />
      <input name="phone" placeholder="Mobile" className="input" required />
      <input name="line1" placeholder="House, street" className="input sm:col-span-2" required />
      <input name="line2" placeholder="Area, landmark" className="input sm:col-span-2" />
      <input name="city" placeholder="City" className="input" required />
      <input name="pincode" placeholder="PIN code" className="input" required maxLength={6} />
      <input name="state" placeholder="State" defaultValue="Tamil Nadu" className="input sm:col-span-2" required />
      {(state?.error || state?.fieldErrors) && <p className="text-xs text-danger sm:col-span-2">{state?.error ?? err("phone") ?? err("pincode") ?? err("line1") ?? "Please check the address fields."}</p>}
      <button disabled={pending} className="btn-outline sm:col-span-2">Save address</button>
    </form>
  );
}

export function DeleteAddressButton({ id }: { id: string }) {
  const [pending, start] = useTransition();
  return (
    <button disabled={pending} onClick={() => start(() => deleteAddress(id))} className="text-xs text-maroon hover:underline">
      Remove
    </button>
  );
}
